def transform(grid):
    """Extend a single obstacle-side motif with a full-length 8 stripe."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = 5
    # The divider is a full straight line of color 2.
    vertical = [c for c in range(w) if all(g[r][c] == 2 for r in range(h))]
    horizontal = [r for r in range(h) if all(v == 2 for v in g[r])]
    if vertical:
        c = vertical[0]
        pts = [(r, x) for r in range(h) for x in range(w) if g[r][x] not in (bg, 2)]
        if not pts:
            return g
        minc, maxc = min(x for r, x in pts), max(x for r, x in pts)
        target = minc - 1 if maxc < c else maxc + 1
        if 0 <= target < w:
            for r in range(h):
                if g[r][target] == bg:
                    g[r][target] = 8
        return g
    if horizontal:
        r0 = horizontal[0]
        pts = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (bg, 2)]
        if not pts:
            return g
        minr, maxr = min(r for r, c in pts), max(r for r, c in pts)
        target = minr - 1 if maxr < r0 else maxr + 1
        if 0 <= target < h:
            for c in range(w):
                if g[target][c] == bg:
                    g[target][c] = 8
        return g
    return g

